CREATE TABLE progress_observations (observation_identity TEXT PRIMARY KEY CHECK(length(observation_identity)=71 AND substr(observation_identity,1,7)='sha256:' AND substr(observation_identity,8) NOT GLOB '*[^0-9a-f]*'), worktree_selector TEXT NOT NULL, terminal_handle TEXT NOT NULL, incarnation_id TEXT NOT NULL, provider TEXT NOT NULL CHECK(provider IN ('codex','claude')), observed_at TEXT NOT NULL, assessment_json TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE progress_projection (worktree_selector TEXT NOT NULL, terminal_handle TEXT NOT NULL, provider TEXT NOT NULL CHECK(provider IN ('codex','claude')), incarnation_id TEXT NOT NULL, state TEXT NOT NULL CHECK(state IN ('running','needs_input','approval_required','verifying','stopped','unknown')), cursor TEXT, observation_identity TEXT NOT NULL REFERENCES progress_observations(observation_identity), observed_at TEXT NOT NULL, updated_at TEXT NOT NULL, PRIMARY KEY(worktree_selector,terminal_handle));
CREATE TABLE progress_report_outbox (sequence INTEGER PRIMARY KEY AUTOINCREMENT, report_id TEXT NOT NULL UNIQUE CHECK(length(report_id)=73 AND substr(report_id,1,9)='progress_' AND substr(report_id,10) NOT GLOB '*[^0-9a-f]*'), worktree_selector TEXT NOT NULL, payload_json TEXT NOT NULL, payload_digest TEXT NOT NULL CHECK(length(payload_digest)=71 AND substr(payload_digest,1,7)='sha256:' AND substr(payload_digest,8) NOT GLOB '*[^0-9a-f]*'), created_at TEXT NOT NULL);
CREATE TABLE progress_delivery_receipts (report_id TEXT PRIMARY KEY REFERENCES progress_report_outbox(report_id), delivered_at TEXT NOT NULL);
CREATE INDEX progress_outbox_pending_order ON progress_report_outbox(sequence);
CREATE TRIGGER immutable_progress_observations_update BEFORE UPDATE ON progress_observations BEGIN SELECT RAISE(ABORT,'immutable progress observation'); END;
CREATE TRIGGER immutable_progress_observations_delete BEFORE DELETE ON progress_observations BEGIN SELECT RAISE(ABORT,'immutable progress observation'); END;
CREATE TRIGGER immutable_progress_outbox_update BEFORE UPDATE ON progress_report_outbox BEGIN SELECT RAISE(ABORT,'immutable progress outbox'); END;
CREATE TRIGGER immutable_progress_outbox_delete BEFORE DELETE ON progress_report_outbox BEGIN SELECT RAISE(ABORT,'immutable progress outbox'); END;
CREATE TRIGGER immutable_progress_receipt_update BEFORE UPDATE ON progress_delivery_receipts BEGIN SELECT RAISE(ABORT,'immutable progress receipt'); END;
CREATE TRIGGER immutable_progress_receipt_delete BEFORE DELETE ON progress_delivery_receipts BEGIN SELECT RAISE(ABORT,'immutable progress receipt'); END;
